import { describe, expect, test } from 'bun:test';
import { setup, expectCode, T0 } from './_harness';

describe('s01 receipts and on-hand', () => {
  test('F01: receive appends a RECEIPT movement and returns it', () => {
    const { ledger } = setup();
    const mv = ledger.receive({ sku: 'BOLT-M8', location: 'WH-1', qty: 40, unitCostCents: 125, ref: 'PO-1' });
    expect(mv.id).toBe('MV-000001');
    expect(mv.type).toBe('RECEIPT');
    expect(mv.sku).toBe('BOLT-M8');
    expect(mv.location).toBe('WH-1');
    expect(mv.qty).toBe(40);
    expect(mv.unitCostCents).toBe(125);
    expect(mv.at).toBe(T0);
  });
  test('F01: on-hand per location and in total', () => {
    const { ledger } = setup();
    ledger.receive({ sku: 'BOLT-M8', location: 'WH-1', qty: 40, unitCostCents: 125 });
    ledger.receive({ sku: 'BOLT-M8', location: 'WH-2', qty: 15, unitCostCents: 125 });
    ledger.receive({ sku: 'TAPE-50', location: 'WH-1', qty: 7, unitCostCents: 300 });
    expect(ledger.onHand('BOLT-M8', 'WH-1')).toBe(40);
    expect(ledger.onHand('BOLT-M8', 'WH-2')).toBe(15);
    expect(ledger.onHand('BOLT-M8', 'STORE-1')).toBe(0);
    expect(ledger.onHand('BOLT-M8')).toBe(55);
    expect(ledger.onHand('TAPE-50')).toBe(7);
  });
  test('F01: unknown sku and location are rejected', () => {
    const { ledger } = setup();
    expectCode(() => ledger.receive({ sku: 'NOPE', location: 'WH-1', qty: 1, unitCostCents: 1 }), 'UNKNOWN_SKU');
    expectCode(() => ledger.receive({ sku: 'BOLT-M8', location: 'NOWHERE', qty: 1, unitCostCents: 1 }), 'UNKNOWN_LOCATION');
    expectCode(() => ledger.onHand('NOPE'), 'UNKNOWN_SKU');
    expectCode(() => ledger.onHand('BOLT-M8', 'NOWHERE'), 'UNKNOWN_LOCATION');
  });
  test('F01: quantity must be a positive integer', () => {
    const { ledger } = setup();
    for (const qty of [0, -3, 1.5])
      expectCode(() => ledger.receive({ sku: 'BOLT-M8', location: 'WH-1', qty, unitCostCents: 1 }), 'INVALID_QTY');
    expect(ledger.movements()).toHaveLength(0);
  });
  test('F01: movements() lists everything in order', () => {
    const { ledger, clock } = setup();
    ledger.receive({ sku: 'BOLT-M8', location: 'WH-1', qty: 1, unitCostCents: 1 });
    clock.advanceHours(2);
    ledger.receive({ sku: 'TAPE-50', location: 'WH-2', qty: 2, unitCostCents: 1 });
    const ms = ledger.movements();
    expect(ms.map((m: any) => m.id)).toEqual(['MV-000001', 'MV-000002']);
    expect(ms[1].at).toBe(clock.iso());
  });
});
