import { describe, expect, test } from 'bun:test';
import { setup, expectCode } from './_harness';

describe('G2 append-only ledger', () => {
  test('G2: correct() appends a REVERSAL and leaves the original untouched', () => {
    const { ledger } = setup();
    const r = ledger.receive({ sku: 'BOLT-M8', location: 'WH-1', qty: 30, unitCostCents: 100 });
    const before = structuredClone(ledger.movements()[0]);
    const rev = ledger.correct(r.id, 'keyed the wrong PO');
    expect(rev.type).toBe('REVERSAL');
    expect(rev.reverses).toBe(r.id);
    expect(rev.qty).toBe(-30);
    expect(rev.sku).toBe('BOLT-M8');
    expect(rev.location).toBe('WH-1');
    const ms = ledger.movements();
    expect(ms).toHaveLength(2);
    expect(ms[0]).toEqual(before);
    expect(ms[1].id).toBe(rev.id);
    expect(ledger.onHand('BOLT-M8', 'WH-1')).toBe(0);
  });
  test('G2: movements() returns copies; editing them changes nothing', () => {
    const { ledger } = setup();
    ledger.receive({ sku: 'BOLT-M8', location: 'WH-1', qty: 30, unitCostCents: 100 });
    const ms = ledger.movements();
    ms[0].qty = 999;
    ms.length = 0;
    expect(ledger.movements()).toHaveLength(1);
    expect(ledger.movements()[0].qty).toBe(30);
    expect(ledger.onHand('BOLT-M8')).toBe(30);
  });
  test('G2: a movement is reversed at most once; reversals are not reversible', () => {
    const { ledger } = setup();
    const r = ledger.receive({ sku: 'BOLT-M8', location: 'WH-1', qty: 30, unitCostCents: 100 });
    const rev = ledger.correct(r.id, 'dup');
    expectCode(() => ledger.correct(r.id, 'again'), 'ALREADY_REVERSED');
    expectCode(() => ledger.correct(rev.id, 'undo'), 'INVALID_REVERSAL');
    expectCode(() => ledger.correct('MV-999999', 'x'), 'UNKNOWN_MOVEMENT');
    expectCode(() => ledger.correct(r.id, '  '), 'ALREADY_REVERSED');
  });
  test('G2: a correction needs a reason', () => {
    const { ledger } = setup();
    const r = ledger.receive({ sku: 'BOLT-M8', location: 'WH-1', qty: 30, unitCostCents: 100 });
    expectCode(() => ledger.correct(r.id, ''), 'REASON_REQUIRED');
    expect(ledger.movements()).toHaveLength(1);
  });
  test('G2: verify() reports a clean ledger after corrections', () => {
    const { ledger } = setup();
    const r = ledger.receive({ sku: 'BOLT-M8', location: 'WH-1', qty: 30, unitCostCents: 100 });
    ledger.receive({ sku: 'BOLT-M8', location: 'WH-1', qty: 5, unitCostCents: 100 });
    ledger.correct(r.id, 'wrong PO');
    const v = ledger.verify();
    expect(v.ok).toBe(true);
    expect(v.problems).toEqual([]);
    expect(ledger.movements()).toHaveLength(3);
  });
});
