import { describe, expect, test } from 'bun:test';
import { setup, expectCode } from './_harness';

describe('G6 movement numbering', () => {
  test('G6: ids are MV- plus a 6-digit, 1-based, gap-free sequence', () => {
    const { ledger } = setup();
    const ids = [];
    for (let i = 0; i < 12; i++) ids.push(ledger.receive({ sku: 'BOLT-M8', location: 'WH-1', qty: 1, unitCostCents: 1 }).id);
    expect(ids[0]).toBe('MV-000001');
    expect(ids[9]).toBe('MV-000010');
    expect(ids[11]).toBe('MV-000012');
  });
  test('G6: a rejected operation consumes no id', () => {
    const { ledger } = setup();
    ledger.receive({ sku: 'BOLT-M8', location: 'WH-1', qty: 1, unitCostCents: 1 });
    expectCode(() => ledger.receive({ sku: 'BOLT-M8', location: 'WH-1', qty: 0, unitCostCents: 1 }), 'INVALID_QTY');
    expectCode(() => ledger.receive({ sku: 'NOPE', location: 'WH-1', qty: 1, unitCostCents: 1 }), 'UNKNOWN_SKU');
    const next = ledger.receive({ sku: 'BOLT-M8', location: 'WH-1', qty: 1, unitCostCents: 1 });
    expect(next.id).toBe('MV-000002');
  });
  test('G6: separate ledgers number independently', () => {
    const a = setup().ledger;
    const b = setup().ledger;
    a.receive({ sku: 'BOLT-M8', location: 'WH-1', qty: 1, unitCostCents: 1 });
    a.receive({ sku: 'BOLT-M8', location: 'WH-1', qty: 1, unitCostCents: 1 });
    expect(b.receive({ sku: 'BOLT-M8', location: 'WH-1', qty: 1, unitCostCents: 1 }).id).toBe('MV-000001');
  });
});
