    const { ledger } = setup();
    rcv(ledger, 'TAPE-50', 'WH-1', 10);
    expectCode(() => ledger.adjust({ sku: 'TAPE-50', location: 'WH-1', qty: -1, reason: '   ' }), 'REASON_REQUIRED');
    expectCode(() => ledger.adjust({ sku: 'TAPE-50', location: 'WH-1', qty: 0, reason: 'x' }), 'INVALID_QTY');
