import { describe, expect, test } from 'bun:test';
import { setup, expectCode, rcv, FAR } from './_harness';

describe('s03 lots', () => {
  test('F03: a perishable receipt needs a lot with an expiry date', () => {
    const { ledger } = setup();
    expectCode(() => ledger.receive({ sku: 'MILK-1L', location: 'WH-1', qty: 5, unitCostCents: 90 }), 'LOT_REQUIRED');
    expectCode(() => ledger.receive({ sku: 'MILK-1L', location: 'WH-1', qty: 5, unitCostCents: 90, lot: { code: 'L1' } }), 'LOT_REQUIRED');
    const mv = ledger.receive({ sku: 'MILK-1L', location: 'WH-1', qty: 5, unitCostCents: 90, lot: { code: 'L1', expiresOn: FAR } });
    expect(mv.lotCode).toBe('L1');
  });
  test('F03: a receipt without a lot forms an anonymous lot named by its movement id', () => {
    const { ledger } = setup();
    rcv(ledger, 'TAPE-50', 'WH-1', 2);
    const mv = rcv(ledger, 'TAPE-50', 'WH-1', 3);
    expect(mv.lotCode).toBe('MV-000002');
    expect(ledger.lots('TAPE-50')).toEqual([
      { code: 'MV-000001', expiresOn: null, location: 'WH-1', qty: 2 },
      { code: 'MV-000002', expiresOn: null, location: 'WH-1', qty: 3 },
    ]);
  });
  test('F03: receipts with the same supplier lot code join one lot', () => {
    const { ledger } = setup();
    rcv(ledger, 'MILK-1L', 'WH-1', 5, 90, { code: 'A7', expiresOn: FAR });
    rcv(ledger, 'MILK-1L', 'WH-1', 4, 90, { code: 'A7', expiresOn: FAR });
    rcv(ledger, 'MILK-1L', 'WH-2', 1, 90, { code: 'A7', expiresOn: FAR });
    expect(ledger.lots('MILK-1L', 'WH-1')).toEqual([{ code: 'A7', expiresOn: FAR, location: 'WH-1', qty: 9 }]);
    expect(ledger.lots('MILK-1L')).toHaveLength(2);
    expectCode(() => rcv(ledger, 'MILK-1L', 'WH-1', 1, 90, { code: 'A7', expiresOn: '2026-11-30' }), 'LOT_MISMATCH');
  });
  test('F03: pickPlan covers the quantity from lots at that location', () => {
    const { ledger } = setup();
    rcv(ledger, 'TAPE-50', 'WH-1', 4);
    rcv(ledger, 'TAPE-50', 'WH-2', 40);
    const plan = ledger.pickPlan('TAPE-50', 'WH-1', 4);
    expect(plan).toEqual([{ lotCode: 'MV-000001', qty: 4 }]);
    expectCode(() => ledger.pickPlan('TAPE-50', 'WH-1', 5), 'INSUFFICIENT_STOCK');
    expectCode(() => ledger.pickPlan('TAPE-50', 'WH-1', 0), 'INVALID_QTY');
  });
  test('F03: a negative adjustment can name its lot', () => {
    const { ledger } = setup();
    rcv(ledger, 'TAPE-50', 'WH-1', 4, 100, { code: 'T1' });
    rcv(ledger, 'TAPE-50', 'WH-1', 4, 100, { code: 'T2' });
    const out = ledger.adjust({ sku: 'TAPE-50', location: 'WH-1', qty: -3, reason: 'crushed', lotCode: 'T2' });
    expect(out.map((m: any) => [m.lotCode, m.qty])).toEqual([['T2', -3]]);
  });
  test('F03: an unnamed negative adjustment draws the oldest lots first, splitting across lots', () => {
    const { ledger } = setup();
    rcv(ledger, 'TAPE-50', 'WH-1', 2, 100, { code: 'OLD' });
