// Binwise never reads the wall clock. Everything that needs "now" takes a
// Clock, and the app runs on a fixed one (fixtures/clock.json).
import clockFixture from '@/fixtures/clock.json';

export type Clock = { now(): Date };

export type FixedClock = Clock & {
  advanceMs(ms: number): void;
  advanceHours(h: number): void;
  advanceDays(d: number): void;
  set(iso: string): void;
};

export function createFixedClock(iso: string): FixedClock {
  let t = Date.parse(iso);
  if (Number.isNaN(t)) throw new Error(`bad clock start: ${iso}`);
  return {
    now: () => new Date(t),
    advanceMs: (ms) => {
      t += ms;
    },
    advanceHours: (h) => {
      t += h * 3_600_000;
    },
    advanceDays: (d) => {
      t += d * 86_400_000;
    },
    set: (next) => {
      t = Date.parse(next);
    },
  };
}

export const FIXTURE_NOW: string = clockFixture.now;
export const appClock = createFixedClock(process.env.BINWISE_NOW ?? FIXTURE_NOW);
EOF
