// Content pins for Chain M: sha256 over each component's files (sorted path +
// bytes), so the published pins prove the sealed chain did not change after
// the freeze without revealing anything in it.
import { createHash } from 'node:crypto';
import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';

const SKIP = new Set(['node_modules', '.next', '.git', 'bun.lock', 'next-env.d.ts', 'validation-report.json']);
function walk(dir: string): string[] {
  return readdirSync(dir).flatMap((n) => {
    if (SKIP.has(n) || n.endsWith('.tsbuildinfo')) return [];
    const p = join(dir, n);
    return statSync(p).isDirectory() ? walk(p) : [p];
  });
}
function pin(root: string) {
  const h = createHash('sha256');
  const files = walk(root).sort();
  for (const f of files) {
    h.update(relative(root, f));
    h.update('\0');
    h.update(readFileSync(f));
    h.update('\0');
  }
  return { sha256: h.digest('hex'), files: files.length };
}
const CHAIN = join(import.meta.dir, '..');
const REF = join(CHAIN, '..', 'binwise-reference-m');
const out = {
  prompts: pin(join(CHAIN, 'prompts')),
  hiddenTests: pin(join(CHAIN, 'hidden-tests')),
  harness: pin(join(CHAIN, 'harness')),
  skeleton: pin(join(CHAIN, 'skeleton')),
  ledgerDocs: (() => {
    const h = createHash('sha256');
    for (const f of ['DECISIONS.md', 'PROBES.md', 'CHAIN.md', 'AUDIT.md']) {
      try {
        h.update(f).update('\0').update(readFileSync(join(CHAIN, f))).update('\0');
      } catch {}
    }
    return { sha256: h.digest('hex') };
  })(),
  reference: pin(join(REF, 'lib')),
};
console.log(JSON.stringify(out, null, 2));
